/**
 * catalog.list: subscribable sources. An empty catalog is an empty sources list.
 */
export interface ConnectorCatalog {
  sources: ConnectorCatalogSource[];
}

/**
 * A stable source id, independent of its display name. Tool names are short and unique within this source.
 */
export interface ConnectorCatalogSource {
  id: string;
  name: string;
  icon?: NavIcon;
  service?: string;
  min_interval_seconds?: number;
  /** A shared connector/account budget, across all its sources. */
  max_calls_per_hour?: number;
  tools: ConnectorCatalogTool[];
  recipes?: ConnectorSubscriptionRecipe[];
}

export interface ConnectorCatalogTool {
  name: string;
  title?: string;
  description: string;
  /** A JSON object containing the tool input schema. */
  input_schema: unknown;
  read_only: boolean;
  annotations?: ConnectorCatalogAnnotations;
}

/**
 * When present, hints must agree with read_only: true and destructive: false.
 */
export interface ConnectorCatalogAnnotations {
  read_only_hint?: boolean;
  destructive_hint?: boolean;
}

/**
 * catalog.call: a source and one of its read-only short tool names. args is an object, default {}.
 */
export interface ConnectorCatalogCallParams {
  contribution: string;
  source: string;
  tool: string;
  args?: unknown;
}

/**
 * items: new items, each kept once; snapshot: the answer as one state, kept when it changes; things: the answer lists
 * Inbox rows ready-made (ConnectorInboxThing), kept and handed to the Inbox as they are.
 */
export type ConnectorSubscriptionMode = "items" | "snapshot" | "things" | (string & {});
export const CONNECTOR_SUBSCRIPTION_MODES = ["items", "snapshot", "things"] as const;

export type ConnectorSubscriptionGroup = "source" | "thread" | (string & {});
export const CONNECTOR_SUBSCRIPTION_GROUPS = ["source", "thread"] as const;

export type ConnectorSubscriptionKind = "sub_mail" | "sub_message" | "sub_notice" | "sub_deadline" | "sub_event" | "sub_update" | "sub_digest" | (string & {});
export const CONNECTOR_SUBSCRIPTION_KINDS = ["sub_mail", "sub_message", "sub_notice", "sub_deadline", "sub_event", "sub_update", "sub_digest"] as const;

/**
 * Paths relative to one item. Only $, .field and [index] are supported; no expressions or recursive descent.
 * sender_id, chat and chat_name name who and where for mutes and policies (the Inbox row's sender and chat tags),
 * seen its read state, and reply_to where a reply goes; none of them is part of an item's content.
 */
export interface ConnectorSubscriptionFields {
  id?: string;
  thread?: string;
  title?: string;
  sender?: string;
  time?: string;
  body?: string;
  link?: string;
  due_date?: string;
  /** The sender's stable id; without it the sender tag is the lowercased display name. */
  sender_id?: string;
  /** The conversation's stable id: the row gets a chat tag. */
  chat?: string;
  /** The conversation's name, the chat tag's name. */
  chat_name?: string;
  /**
   * Whether the item was already seen in the source: true, a non-zero number, or true, 1, yes, read or seen in any
   * case. The Inbox row is read when its newest item is; seen only ever turns on.
   */
  seen?: string;
  /**
   * Where a reply goes and who sees it, in a line for people. With it, an item with an id can be replied to through
   * the connector's inbox reply, with its thread (else its id) and its id as last.
   */
  reply_to?: string;
}

/**
 * A pull recipe, not a schedule. In things mode the rows bring their own threads and kinds: group_by is thread, kind
 * is a row's when it has none, and fields and pagination are not used. args is an object (default {}); strings may
 * contain {{since}} or {{since_date}}. cursor_arg and next_cursor_path opt into cursor pagination; page_arg and
 * optional next_page_path opt into page pagination (without next_page_path, a full requested page continues).
 * items_path defaults to $; fields are relative to one item. Text results require snapshot mode. Runtime
 * argument/schema and mapped-value validation belongs to the subscription runner.
 */
export interface ConnectorSubscriptionRecipe {
  mode: ConnectorSubscriptionMode;
  tool: string;
  args?: unknown;
  cursor_arg?: string;
  next_cursor_path?: string;
  page_arg?: string;
  next_page_path?: string;
  items_path?: string;
  fields?: ConnectorSubscriptionFields;
  kind: ConnectorSubscriptionKind;
  group_by: ConnectorSubscriptionGroup;
}

/**
 * error.code a program answers or gets besides the base ErrorCode: rate_limited (tools.call / actions.do, and the
 * hub's answer to too many sent.record; data {retry_after} in seconds, fractional allowed), why credentials.gh_token
 * has no token, and what recall answers: not_recallable (nothing was sent: the program cannot take that message back)
 * and recall_unknown (the request may have taken effect). not_signed_in, offline and rate_limited also say that
 * recall could not act now. not_read_only refuses a catalog.call outside the current read-only catalog.
 */
export type ConnectorErrorCode = "rate_limited" | "no_machine" | "offline" | "node_too_old" | "no_gh" | "not_signed_in" | "not_recallable" | "recall_unknown" | "not_read_only" | (string & {});
export const CONNECTOR_ERROR_CODES = ["rate_limited", "no_machine", "offline", "node_too_old", "no_gh", "not_signed_in", "not_recallable", "recall_unknown", "not_read_only"] as const;

/**
 * What a connector declares (ConnectorItem.capabilities): the hub calls only the methods of declared ones. fallback
 * has no method: every inbox thing promises extra.rule_tier. recall is the program's word that it can take back what
 * it sent: the hub calls recall.can / recall.do after the user agreed, or legacy connector.recall for a program
 * without those methods, and the install preview says so. history (needs archive) is history.chats and
 * archive.history, history_anchors (needs history) is history.anchors. catalog lists subscribable read-only sources
 * and calls their short tool names. An extension's connector with one this hub does not know loses only that
 * capability.
 */
export type ConnectorCapability = "status" | "tools" | "actions" | "events" | "inbox" | "settle" | "archive" | "chats" | "items" | "login" | "options" | "threads" | "snapshot" | "group" | "meta" | "fallback" | "machines" | "recall" | "history" | "history_anchors" | "catalog" | (string & {});
export const CONNECTOR_CAPABILITIES = ["status", "tools", "actions", "events", "inbox", "settle", "archive", "chats", "items", "login", "options", "threads", "snapshot", "group", "meta", "fallback", "machines", "recall", "history", "history_anchors", "catalog"] as const;

/**
 * ConnectorStatus.state. disabled is the hub's own (the user switched it off); a program never answers it.
 */
export type ConnectorState = "ok" | "not_configured" | "not_signed_in" | "no_permission" | "rate_limited" | "error" | "disabled" | (string & {});
export const CONNECTOR_STATES = ["ok", "not_configured", "not_signed_in", "no_permission", "rate_limited", "error", "disabled"] as const;

/**
 * What changed (ConnectorChangedEvent.scope): the knowledge base's chats or items, or the inbox. Another scope is
 * dropped and logged.
 */
export type ConnectorScope = "chats" | "items" | "inbox" | (string & {});
export const CONNECTOR_SCOPES = ["chats", "items", "inbox"] as const;

/**
 * An inbox thing's tier by the connector's own rules: needs the user, worth knowing, noise. Empty leaves it to the
 * model.
 */
export type ConnectorTier = "action" | "fyi" | "noise" | (string & {});
export const CONNECTOR_TIERS = ["action", "fyi", "noise"] as const;

/**
 * ConnectorInboxThing.done: the thread is over without the user (read), or the user answered (replied).
 */
export type ConnectorDone = "read" | "replied" | (string & {});
export const CONNECTOR_DONES = ["read", "replied"] as const;

/**
 * ConnectorTag.key values the hub knows: the user can mute by repo, chat and sender. Others are kept for rules.
 */
export type ConnectorTagKey = "repo" | "chat" | "sender" | "branch" | (string & {});
export const CONNECTOR_TAG_KEYS = ["repo", "chat", "sender", "branch"] as const;

/**
 * ConnectorPrompt.kind besides fields to fill in (empty): a code to enter on a web page, or a URL to scan as a QR
 * code. For both the app asks the same step again, without values, every interval seconds.
 */
export type ConnectorPromptKind = "device_code" | "qr" | (string & {});
export const CONNECTOR_PROMPT_KINDS = ["device_code", "qr"] as const;

/**
 * What connector.posts.put says of each post: first time in the archive, its comment count moved, or refused (no id,
 * or another connector's). An empty string is a post seen unchanged.
 */
export type ConnectorPostStatus = "new" | "changed" | "refused" | (string & {});
export const CONNECTOR_POST_STATUSES = ["new", "changed", "refused"] as const;

/**
 * The tools a grouping connector answers in group.tool (the model reads the conversation with them); another may
 * answer unknown_method.
 */
export type ConnectorGroupTool = "messages_before" | "messages_around" | "search" | (string & {});
export const CONNECTOR_GROUP_TOOLS = ["messages_before", "messages_around", "search"] as const;

/**
 * An answer with nothing in it: {}.
 */
export interface Empty {
}

/**
 * init, the bare opening of protocol 2 without the extension protocol (kept one release; the hub opens with
 * initialize). Answered with ConnectorManifest.
 */
export interface ConnectorInitParams {
  protocol: 2;
  /** The connector's settings. */
  config?: unknown;
}

/**
 * What the program says it is: init's answer, and connector.manifest's. The fields are ConnectorItem's
 * (manifest.schema.json) with the protocol.
 */
export interface ConnectorManifest {
  protocol: number;
  id: string;
  name: string;
  capabilities: string[];
  hosts?: string[];
  agent_tools?: string[];
  unlisted?: string[];
  confirm_always?: string[];
  poll_seconds?: number;
  kinds?: string[];
  archive_sources?: string[];
  meta_description?: string;
  cli?: string;
}

/**
 * The params of a call without any of its own (status, tools.list, actions.list, inbox.collect, items.list, logout,
 * options.get, auth.get; secrets.load, secrets.delete).
 */
export interface ConnectorParams {
  contribution: string;
}

/**
 * connector.status: how the connector is doing, from memory (no network; the hub asks every 30 seconds). Only an ok
 * connector offers tools.
 */
export interface ConnectorStatus {
  state: ConnectorState;
  /** Who it reads as, for display. */
  account?: string;
  /** Where the sign-in comes from. */
  via?: string;
  /** One sentence for people when state is not ok; never a secret. */
  error?: string;
  /** How to fix it, a step a sentence. */
  guide?: string[];
  /** Optional HTTPS page the App may open for the fix; never a secret. */
  guide_url?: string;
  /** Permissions the connector can identify as absent. */
  missing_scopes?: string[];
  last_sync?: string;
  last_event?: string;
}

/**
 * A read tool (tools.list) or a write (actions.list): its name starts with <connector id>_.
 */
export interface ConnectorTool {
  name: string;
  description: string;
  /** A JSON Schema with type object. */
  input_schema: unknown;
  /**
   * Words that run the tool in a shell instead (a gated command's); runtimes refuse them in an assistant
   * conversation.
   */
  shell?: string[];
}

/**
 * tools.list and actions.list.
 */
export interface ConnectorTools {
  tools?: ConnectorTool[];
}

/**
 * tools.call, and actions.describe (what the phone's card says before a write).
 */
export interface ConnectorCallParams {
  contribution: string;
  name: string;
  args?: unknown;
}

/**
 * tools.call and actions.do.
 */
export interface ConnectorCallResult {
  text?: string;
  /**
   * actions.do only (tools.call ignores it): the id, on the other side, of the message the write made, when the
   * service gave one (a comment's id, a mail's Message-ID, a chat message's id). The hub trims it and keeps it as the
   * sent-as-user ledger row's message_ref; one longer than 200 characters is dropped (the row has none), not cut.
   * Leave it out when there is none.
   */
  message_ref?: string;
}

/**
 * A write as the card names it: visible says who will see it.
 */
export interface ConnectorAction {
  name?: string;
  visible?: string;
}

/**
 * actions.describe: the card's action and its full content. No network; an error refuses the call before the user is
 * asked.
 */
export interface ConnectorDescribeResult {
  action: ConnectorAction;
  summary: string;
}

/**
 * actions.do, only once the hub's gate let the write through: the very args of the card, and the hub's id for this
 * run (the same if it is ever sent again: the program runs it once).
 */
export interface ConnectorDoParams {
  contribution: string;
  name: string;
  args?: unknown;
  request_id: string;
}

/**
 * recall: take back a message the connector's program sent in the user's name, which the sent-as-user ledger has a
 * row of (docs/extensions/connectors.md "Sent as the user"). Only for a connector that declares the capability
 * recall, and only once the user agreed on their own device; the program never starts one. The fields are the row's,
 * as the hub kept them: nothing of what the message said. A repeat after success is a success too. Answer with
 * ConnectorRecallResult (recalled true) only when the service confirms the message is no longer there, one that was
 * already gone included; otherwise an error: not_recallable (it cannot, and nothing was sent), not_signed_in, offline
 * or rate_limited (it cannot act now), recall_unknown (it may have gone through), any other error is the service
 * refusing, with one sentence for people (no secret, no text of the message).
 */
export interface ConnectorRecallParams {
  contribution: string;
  /**
   * What wrote it: the tool's name (actions.do), sent.record, or, for a write the node's gate forwarded, "METHOD
   * /path".
   */
  action: string;
  /**
   * The sent message's id on the other side, as the program gave it (actions.do or sent.record) or as the service's
   * answer did (a write through the node's gate).
   */
  message_ref: string;
  /**
   * Where it went, as the ledger kept it (short values): the program's own for a send it recorded; for a write
   * through the node's gate also method, path and command (the gate's name), and the ids its path names.
   */
  target?: Record<string, unknown>;
  /** When the ledger wrote the row, right after the send. */
  at?: string;
}

/**
 * Legacy recall's answer: recalled true is the program's word that the service confirmed the message is no longer
 * there. Anything else (no recalled, false) is not taken for a yes: the hub then knows nothing, writes nothing and
 * lets the user ask again.
 */
export interface ConnectorRecallResult {
  recalled: boolean;
}

/**
 * recall.can's read-only, memory-only preflight. The hub asks it immediately before recall.do, not for every row of a
 * ledger page. age_seconds is the sent row's age, clamped at zero for a future timestamp.
 */
export interface ConnectorRecallCanParams {
  contribution: string;
  action: string;
  age_seconds: number;
}

/**
 * recall.can's answer. can false stops before any write and means not_recallable.
 */
export interface ConnectorRecallCanResult {
  can: boolean;
}

/**
 * recall.do takes back one message after the user agreed on their own full device. request_id is stable for this
 * connector and external message: concurrent duplicates share one operation, and a confirmed success can be replayed
 * after a lost answer. A failure or unknown outcome may be tried again explicitly. at is retained for connectors
 * whose own recall window counts from the send. No message text, origin, approval record, account or credential is
 * included.
 */
export interface ConnectorRecallDoParams {
  contribution: string;
  request_id: string;
  action: string;
  message_ref: string;
  target?: Record<string, unknown>;
  at?: string;
}

/**
 * recall.do's outcome. Only done and already_recalled say the message is known to be gone. unknown may have taken
 * effect and is never success.
 */
export type ConnectorRecallOutcome = "done" | "already_recalled" | "not_recallable" | "unavailable" | "refused" | "unknown" | (string & {});
export const CONNECTOR_RECALL_OUTCOMES = ["done", "already_recalled", "not_recallable", "unavailable", "refused", "unknown"] as const;

/**
 * recall.do's result. error is one human-readable sentence for a non-success status, never a secret or the message's
 * text. An empty or unrecognized status is treated as unknown by the hub.
 */
export interface ConnectorRecallDoResult {
  status: ConnectorRecallOutcome;
  error?: string;
}

/**
 * thread.page: one page of an inbox thread, oldest first; no before is the newest page.
 */
export interface ConnectorThreadParams {
  contribution: string;
  thread: string;
  before?: string;
  limit?: number;
}

/**
 * thread.page's answer: before goes back one more page (none: the start).
 */
export interface ConnectorThreadPage {
  chat: ConnectorThreadChat;
  messages: ConnectorThreadMessage[];
  before?: string;
}

/**
 * The conversation the thread is. state … body_format are a pull request's or an issue's.
 */
export interface ConnectorThreadChat {
  id: string;
  name: string;
  /** dm, group, channel (bubbles); pr, issue. */
  kind: string;
  url?: string;
  /** A media ref (thread.media). */
  avatar?: string;
  members?: number;
  /** The action that answers here, with {chat: <thread>, text, reply_to}; none when the user cannot. */
  reply?: string;
  /** open, merged, closed or draft. */
  state?: string;
  author?: ConnectorThreadPerson;
  labels?: ConnectorThreadLabel[];
  branch?: ConnectorThreadBranch;
  body?: string;
  /** Empty or markdown. */
  body_format?: string;
}

export interface ConnectorThreadMessage {
  id: string;
  at: string;
  sender: ConnectorThreadPerson;
  mine?: boolean;
  /** A line of the thread's own (joined, renamed, merged): no bubble. */
  event?: boolean;
  text?: string;
  /** Empty or markdown. */
  format?: string;
  media?: ConnectorThreadMedia[];
  reply_to?: ConnectorThreadQuote;
  edited?: boolean;
  url?: string;
  /** Empty for a message; review, code (a comment on a line), check (CI). */
  kind?: string;
  /** approved, changes_requested, commented or dismissed. */
  review?: string;
  code?: ConnectorThreadCode;
  check?: ConnectorThreadCheck;
}

export interface ConnectorThreadPerson {
  id?: string;
  name: string;
  /** A media ref. */
  avatar?: string;
}

/**
 * A picture, sticker, video, voice message or file: ref and thumb are media refs; a file or voice message is only
 * described.
 */
export interface ConnectorThreadMedia {
  /** image, sticker, video, voice or file. */
  kind: string;
  ref?: string;
  thumb?: string;
  mime?: string;
  name?: string;
  size?: number;
  /** Seconds. */
  duration?: number;
  width?: number;
  height?: number;
  /** A sticker's. */
  emoji?: string;
}

/**
 * The message another one answers, as much as the page could tell.
 */
export interface ConnectorThreadQuote {
  id: string;
  from?: string;
  text?: string;
}

export interface ConnectorThreadLabel {
  name: string;
  /** Six hex digits. */
  color?: string;
}

export interface ConnectorThreadBranch {
  head: string;
  base: string;
}

/**
 * The line a code comment is on, and the end of the diff before it.
 */
export interface ConnectorThreadCode {
  path: string;
  line?: number;
  hunk?: string;
}

/**
 * A CI run: success, failure, pending, skipped or cancelled, and a failed one's log end (at most 8 KB).
 */
export interface ConnectorThreadCheck {
  name: string;
  state: string;
  url?: string;
  log?: string;
}

/**
 * thread.media and archive.media: a ref the connector made. Refs never change meaning (the app caches them for good).
 */
export interface ConnectorMediaParams {
  contribution: string;
  ref: string;
}

/**
 * Media bytes, base64: at most 4 MB from thread.media, 20 MB from archive.media.
 */
export interface ConnectorMedia {
  mime: string;
  /** Base64. */
  data: string;
}

/**
 * inbox.collect, from memory: the threads that may need the user.
 */
export interface ConnectorCollectResult {
  things?: ConnectorInboxThing[];
}

/**
 * One thread that may need the user; the hub makes inbox items of them. With group it is a batch of a conversation's
 * new messages instead (docs "Event grouping"); with id and meta it is an event (group.append's answer).
 */
export interface ConnectorInboxThing {
  /** The connector's stable key of the thread. */
  thread: string;
  /** One of the manifest's kinds. */
  kind: string;
  label?: string;
  title?: string;
  sender?: string;
  preview?: string;
  /** The thread as text, for triage, drafting and the AI twin. */
  context?: string;
  at?: string;
  /** Marks the newest move: a different last adds to the open item. */
  last?: string;
  url?: string;
  /** A link the system opens instead (sms:…). */
  open_url?: string;
  /** Where a reply goes and who sees it. */
  reply_to?: string;
  can_reply?: boolean;
  /** ConnectorTier, or empty for the model. */
  tier?: string;
  why?: string;
  /** The user's own triage rules for this source or account; when set the model gets them instead of the hub's. */
  rules?: string;
  /** ConnectorDone: ends the open item. */
  done?: string;
  read?: boolean;
  tags?: ConnectorTag[];
  extra?: ConnectorThingExtra;
  group?: ConnectorThingGroup;
  id?: string;
  /** An event's own state, kept and handed back by the hub as it is. */
  meta?: unknown;
  parent?: ConnectorThingParent;
}

export interface ConnectorTag {
  /** ConnectorTagKey, or the connector's own. */
  key: string;
  value: string;
  name?: string;
}

/**
 * Fields beyond the generic thing: rule_tier for a fallback connector; the rest only for a connector taking over one
 * of the hub's own (lark, github).
 */
export interface ConnectorThingExtra {
  source?: string;
  account?: string;
  account_name?: string;
  legacy_id?: string;
  avatar?: string;
  count?: number;
  started_at?: string;
  rule_tier?: string;
  lark?: unknown;
  doc?: unknown;
  moment?: unknown;
}

/**
 * A batch to relate: its id (the same each time the batch is handed again) and its new messages' ids.
 */
export interface ConnectorThingGroup {
  batch: string;
  new: string[];
}

/**
 * What the thing grew out of: kind inbox (an item's id), todo (a todo's id) or session (<machine>/<session>).
 */
export interface ConnectorThingParent {
  kind: string;
  id: string;
}

/**
 * inbox.reply: the user pressed Send, itself the confirmation. client_id makes a retry go out once; changes move a
 * document row's status first (text may then be empty).
 */
export interface ConnectorInboxReply {
  contribution: string;
  thread: string;
  item_id?: string;
  last?: string;
  text?: string;
  client_id?: string;
  changes?: ConnectorStatusChange[];
}

export interface ConnectorStatusChange {
  ref: string;
  field: string;
  value: string;
}

/**
 * inbox.settle: the threads of the items the hub still has open.
 */
export interface ConnectorSettleParams {
  contribution: string;
  threads: string[];
}

/**
 * inbox.settle's answer: why each thread that is over is (the hub files them done).
 */
export interface ConnectorSettled {
  settled?: Record<string, string>;
}

/**
 * group.tool: one of ConnectorGroupTool for the model, args as the model wrote them. Answered with any JSON.
 */
export interface ConnectorGroupToolParams {
  contribution: string;
  thread: string;
  name: string;
  args?: unknown;
}

/**
 * group.append (meta): add messages to one event, an existing one (event and its meta) or a new one (event empty,
 * meta null: meta is always there) that may continue a done one. Answered with the event as a ConnectorInboxThing
 * with id and meta.
 */
export interface ConnectorGroupAppendParams {
  contribution: string;
  thread: string;
  event: string;
  meta: unknown;
  messages: string[];
  continues?: string;
}

/**
 * group.fallback: group a batch by structure, with the conversation's events.
 */
export interface ConnectorGroupFallbackParams {
  contribution: string;
  thread: string;
  batch: string;
  events: ConnectorGroupEvent[];
}

export interface ConnectorGroupEvent {
  id: string;
  meta: unknown;
  done: boolean;
}

/**
 * group.fallback's answer: each new message exactly once, in an open event given (assign) or a new one (new).
 */
export interface ConnectorGroupFallback {
  assign: ConnectorGroupAssign[];
  new: ConnectorGroupNew[];
}

export interface ConnectorGroupAssign {
  message: string;
  event: string;
}

export interface ConnectorGroupNew {
  key: string;
  messages: string[];
  rule_tier?: string;
  title?: string;
}

/**
 * archive.changes: the program's own cursor, kept and handed back as it is (empty the first time).
 */
export interface ConnectorChangesParams {
  contribution: string;
  cursor?: string;
  limit?: number;
}

/**
 * archive.changes' answer: what moved since the cursor, where to go on from, and whether another call has more now.
 */
export interface ConnectorChangesResult {
  batches?: ConnectorChatBatch[];
  next?: string;
  more?: boolean;
}

/**
 * One conversation's new messages, oldest first, archived as the chat <source>-<chat.id>: no source is the
 * connector's id, else one of the manifest's archive_sources.
 */
export interface ConnectorChatBatch {
  source?: string;
  chat?: ConnectorArchiveChat;
  messages?: ConnectorArchiveMessage[];
}

/**
 * A batch's conversation. The flags are what the owner set at the source (none: not set, or the program cannot tell);
 * the knowledge base's selection matches its rules on them and on kind, and a flag a program never reports never
 * matches its rule.
 */
export interface ConnectorArchiveChat {
  id: string;
  name: string;
  /**
   * The selection's kind rules match dm, group, bot, official (an official or service account) and system (the
   * service's own notices); a source may report other kinds (mail, issue, pr…), which match no kind rule.
   */
  kind: string;
  topic?: boolean;
  /** The owner muted it (a source's automatic muting of large groups included). */
  muted?: boolean;
  /** The owner folded it away (a chat box, folded groups). */
  collapsed?: boolean;
  /** The owner marked it done. */
  done?: boolean;
  updated_at?: string;
}

/**
 * One archived message. The archive only appends: a message without at, or without text and media, is dropped.
 */
export interface ConnectorArchiveMessage {
  id: string;
  position?: string;
  sender_id?: string;
  sender_name?: string;
  mine?: boolean;
  /**
   * The owner is mentioned by name in it (an @-mention of the owner, or the owner's display names): the program
   * decides, on archive.changes batches and history pages alike. An @all alone is mentioned_all.
   */
  mentioned?: boolean;
  /**
   * It mentions everyone in the chat (an @all / @everyone). Reported apart from mentioned: whether it counts as a
   * mention is the knowledge base's selection (include_all).
   */
  mentioned_all?: boolean;
  /** TEXT, POST, IMAGE, FILE, CARD, SYSTEM… */
  type?: string;
  text?: string;
  at?: string;
  /** Refs for archive.media. */
  media?: string[];
  /** Raw identity clues; the hub keeps only their HMAC. */
  sender_handles?: KBHandle[];
}

/**
 * history.chats: the conversations the connector can import the history of. Read-only.
 */
export interface ConnectorHistoryChats {
  chats: ConnectorHistoryChat[];
}

/**
 * One conversation to import: estimate is roughly how many messages it has (0 or none: unknown); source is the name
 * it is filed under, as a batch's (none: the connector's id). id alone names it, unique across the connector's
 * sources.
 */
export interface ConnectorHistoryChat {
  id: string;
  name: string;
  kind: string;
  /** As an archive chat's muted, collapsed and done. */
  muted?: boolean;
  collapsed?: boolean;
  done?: boolean;
  bot?: boolean;
  estimate?: number;
  source?: string;
}

/**
 * archive.history: one page of a conversation, older than before, newer than after, or around a position (at most
 * one; none: the newest page). Positions and cursors are the program's own strings. limit is a hint (the hub sends at
 * most 200; 0 or none: the program's default) and a program may answer more.
 */
export interface ConnectorHistoryParams {
  contribution: string;
  chat: string;
  before?: string;
  after?: string;
  around?: string;
  limit?: number;
}

/**
 * archive.history's answer, messages oldest first. older is the cursor to go further back and more says there is
 * older history. Read in this order, since a paced or unreadable page is empty with more false too: pace asks the hub
 * to wait or stop and never means the start; unreadable: the account can no longer read the conversation (left,
 * dissolved, not found), permanent, with no messages, not an error; otherwise more false (or no messages) is the
 * start of the conversation.
 */
export interface ConnectorHistoryPage {
  messages?: ConnectorArchiveMessage[];
  older?: string;
  newer?: string;
  more?: boolean;
  unreadable?: boolean;
  pace?: ConnectorPace;
}

/**
 * How fast the program may be read: retry_after_ms is ask again no sooner (a rate limit), stop is wait for a person
 * (an expired sign-in, a refusal); reason is for people and never a secret. The hub never sends a read that timed out
 * again.
 */
export interface ConnectorPace {
  retry_after_ms?: number;
  stop?: boolean;
  reason?: string;
}

/**
 * history.anchors: the messages the owner sent or was mentioned in between since and until, in one conversation
 * (chat) or all of them (none); cursor is the next of the call before. limit is a hint, as archive.history's.
 */
export interface ConnectorHistoryAnchorsParams {
  contribution: string;
  chat?: string;
  since?: string;
  until?: string;
  cursor?: string;
  limit?: number;
}

/**
 * history.anchors' answer: next is the cursor for the next call, more says there are more.
 */
export interface ConnectorHistoryAnchors {
  anchors?: ConnectorHistoryAnchor[];
  next?: string;
  more?: boolean;
  pace?: ConnectorPace;
}

/**
 * One message the owner sent (mine) or was mentioned in (mention), at position in chat: the hub reads the page around
 * it. message is the hit itself, the only way to keep one from a conversation that is unreadable now; a search hit
 * may have no sender_id. source is the name the conversation is filed under, as a chat's source (a conversation the
 * account left is often missing from history.chats).
 */
export interface ConnectorHistoryAnchor {
  chat: string;
  source?: string;
  position: string;
  at?: string;
  mine?: boolean;
  mention?: boolean;
  message?: ConnectorArchiveMessage;
}

/**
 * items.list: the knowledge base's documents, meetings and events.
 */
export interface ConnectorItems {
  items: ConnectorKBItem[];
}

/**
 * One knowledge-base item. The fields after where are the knowledge base's own (its tagging); a program leaves them
 * out.
 */
export interface ConnectorKBItem {
  kind: string;
  /**
   * The connector the item belongs to. A program may leave it out: the knowledge base sets it to the calling
   * connector's id, whatever the program sends.
   */
  source?: string;
  id: string;
  title: string;
  url?: string;
  at?: string;
  /** Where it came from (a chat id, calendar…). */
  where?: string;
  projects?: string[];
  note?: string;
  seen?: string;
  /**
   * Why it concerns the owner, as far as the program can tell: mentions (the document mentions the owner),
   * comment_mentions (a comment or reply on it does), authored (the owner owns it), viewed (the owner opened it
   * recently). The knowledge base's selection keeps documents by them; leave out what the program cannot tell.
   */
  signals?: string[];
  importance?: string;
  relevance?: number;
  tags?: string[];
  locked?: boolean;
  tagged_at?: string;
  pinned?: string;
  locked_fields?: string[];
  /** The store's: which extension holds a locked field. A connector's is ignored. */
  provenance?: Record<string, ConnectorKBProvenance>;
}

/**
 * Who holds a locked field of a knowledge-base entity, and from what (kb.schema.json KBProvenance).
 */
